import 'dart:async';
import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

/// One bundled npm package (name + version), read from the CI-produced
/// `assets/toolbox/modules.json` manifest. The manifest is generated by
/// `.github/workflows/bundle-opencode.yml` at bundle time and lists every
/// package pre-installed under `toolbox/lib/node_modules/` — i.e. every
/// module the embedded opencode runtime + chat modules can `require()`
/// without a per-script install.
class BundledModule {
  const BundledModule({required this.name, this.version = ''});

  final String name;
  final String version;

  factory BundledModule.fromJson(Map<String, dynamic> json) => BundledModule(
    name: (json['name'] ?? '').toString(),
    version: (json['version'] ?? '').toString(),
  );

  @override
  String toString() => version.isEmpty ? name : '$name@$version';
}

/// Categorized view of the bundled Node toolbox. Mirrors the shape written
/// by the CI manifest step in `bundle-opencode.yml`.
class ToolboxManifest {
  const ToolboxManifest({
    this.generatedAt = '',
    this.nodeRuntime = 'bundled-per-abi',
    this.crypto = const <BundledModule>[],
    this.dev = const <BundledModule>[],
    this.browser = const <BundledModule>[],
    this.all = const <BundledModule>[],
    this.version = '',
    this.isPresent = false,
  });

  /// ISO timestamp the manifest was generated (CI bundle time).
  final String generatedAt;

  /// How the Node runtime itself is shipped — always `bundled-per-abi`
  /// (the bridge picks node-<abi> or libnode.so at runtime).
  final String nodeRuntime;

  /// Crypto / web3 packages: ethers, web3, viem, @solana/web3.js,
  /// bitcoinjs-lib, @noble/* , bip39, bip32, hdkey, crypto-js, bs58,
  /// tweetnacl. Native-addon equivalents (secp256k1) are replaced with
  /// their @noble/* pure-JS counterparts so the toolbox runs under any
  /// Android Node runtime without a toolchain.
  final List<BundledModule> crypto;

  /// Developer tooling: typescript, esbuild, tsx, prettier, vitest, zx,
  /// commander, chalk, dotenv, axios, lodash, zod, date-fns, p-map,
  /// p-queue, node-fetch.
  final List<BundledModule> dev;

  /// Browser automation: agent-browser (Rust musl-static per-ABI binary,
  /// with a JS shim fallback) + playwright-core (pure-JS API only).
  final List<BundledModule> browser;

  /// Every bundled package, alphabetical.
  final List<BundledModule> all;

  /// Toolbox revision string from `assets/toolbox/version.txt`
  /// (`opencode-<sha>+toolbox-<sha>`).
  final String version;

  /// False when the manifest asset is absent (the CI bundle has not been
  /// staged into this build yet). The UI uses this to show an "install the
  /// toolbox" hint instead of an empty list.
  final bool isPresent;

  int get totalModules => all.length;
}

/// Loads the bundled-toolbox manifest from APK assets. Pure Dart + rootBundle,
/// so it works in tests with a mocked asset bundle and never touches the
/// platform channel. The manifest is small (~tens of KB), so it is cached
/// in-process after the first read.
class ToolboxManifestLoader {
  ToolboxManifestLoader._();
  static final ToolboxManifestLoader instance = ToolboxManifestLoader._();

  static const String _manifestAsset = 'assets/toolbox/modules.json';
  static const String _versionAsset = 'assets/toolbox/version.txt';

  ToolboxManifest? _cache;
  bool _loaded = false;

  /// Returns the cached manifest if already loaded, otherwise loads it.
  /// Never throws — a missing/corrupt asset yields
  /// [ToolboxManifest.isPresent] == false.
  Future<ToolboxManifest> load() async {
    if (_loaded && _cache != null) return _cache!;
    _cache = await _loadFresh();
    _loaded = true;
    return _cache!;
  }

  /// Forces a re-read (used by the Settings → opencode refresh button).
  Future<ToolboxManifest> reload() async {
    _cache = await _loadFresh();
    _loaded = true;
    return _cache!;
  }

  Future<ToolboxManifest> _loadFresh() async {
    String manifestRaw;
    try {
      manifestRaw = await rootBundle.loadString(_manifestAsset);
    } catch (_) {
      // The CI bundle has not been staged into this build. Surface an
      // empty, isPresent=false manifest so the UI can hint the user.
      return const ToolboxManifest(isPresent: false);
    }
    String version;
    try {
      version = (await rootBundle.loadString(_versionAsset)).trim();
    } catch (_) {
      version = '';
    }
    try {
      final decoded = jsonDecode(manifestRaw);
      if (decoded is! Map<String, dynamic>) {
        return ToolboxManifest(version: version, isPresent: true);
      }
      return ToolboxManifest(
        generatedAt: (decoded['generatedAt'] ?? '').toString(),
        nodeRuntime: (decoded['nodeRuntime'] ?? 'bundled-per-abi').toString(),
        crypto: _toList(decoded['crypto']),
        dev: _toList(decoded['dev']),
        browser: _toList(decoded['browser']),
        all: _toList(decoded['all']),
        version: version,
        isPresent: true,
      );
    } catch (_) {
      return ToolboxManifest(version: version, isPresent: true);
    }
  }

  List<BundledModule> _toList(Object? raw) {
    if (raw is! List) return const <BundledModule>[];
    return raw
        .whereType<Map<String, dynamic>>()
        .map(BundledModule.fromJson)
        .where((m) => m.name.isNotEmpty)
        .toList();
  }
}
